// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    RecipientRejector badRecipient;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 actorNonce) public {
        amount = bound(amount, 0, 1 ether);

        badRecipient = new RecipientRejector();

        vm.deal(address(c), 1 ether);

        vm.prank(address(this));

        SimpleWallet c2 = badRecipient.deployC();

        vm.deal(address(c2), 1 ether);

        vm.prank(address(badRecipient));

        bool ok;
        try c2.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c2).balance == (1 ether - amount));
        } else {
            assertTrue(address(c2).balance == 1 ether);
        }
    }
}

contract RecipientRejector {
    receive() external payable {
        revert("reject");
    }
    fallback() external payable {
        revert("reject");
    }
    function deployC() external returns (SimpleWallet) {
        SimpleWallet newc = new SimpleWallet();
        return newc;
    }
}
